public class CollectionUtils {
    // Generic method with bounded type parameter
    public static <T extends Comparable<T>> T max(Collection<T> collection) {
        if (collection == null || collection.isEmpty()) {
            throw new IllegalArgumentException("Collection must not be null or empty");
        }
        Iterator<T> iterator = collection.iterator();
        T candidate = iterator.next();
        while (iterator.hasNext()) {
            T current = iterator.next();
            if (current.compareTo(candidate) > 0) {
                candidate = current;
            }
        }
        return candidate;
    }

    // Generic constructor within a non-generic class
    public static class Box {
        private final Object content;

        public <U> Box(U item, Class<U> type) {
            this.content = type.cast(item);
        }

        public Object getContent() {
            return content;
        }
    }
}
